def get_scale_values(scale_preset: str, custom_h: float, custom_v: float) -> tuple[float, float]:
    """Return (horizontal, vertical) factors for a preset name; "Custom" uses the inputs."""
    factor = SCALE_PRESETS.get(scale_preset)
    return (custom_h, custom_v) if factor is None else (factor, factor)

def resize(image: torch.Tensor, h_scale: float, v_scale: float) -> torch.Tensor:
    """Bilinearly resize a ComfyUI IMAGE batch (B, H, W, C)."""
    if h_scale == 1.0 and v_scale == 1.0:
        return image
    _, height, width, _ = image.shape
    size = (max(1, int(height * v_scale)), max(1, int(width * h_scale)))
    resized = F.interpolate(
        image.permute(0, 3, 1, 2), size=size, mode="bilinear", align_corners=False
    )
    return resized.permute(0, 2, 3, 1).clamp(0.0, 1.0)

def get_preset(name: str) -> dict:
    """Get preset by name, returns clean_ntsc if not found."""
    return PRESETS.get(name, PRESETS["clean_ntsc"]).copy()

def get_preset_names() -> list:
    """Get list of available preset names."""
    return list(PRESETS.keys())

def get_preset_display_name(name: str) -> str:
    """Get display name for a preset."""
    preset = get_preset(name)
    return preset.get("display_name", name.replace("_", " ").title())

def main() -> int:
    removed = 0
    for directory in DIRECTORIES:
        if directory.exists():
            shutil.rmtree(directory)
            print(f"Removed {directory.relative_to(ROOT)}")
            removed += 1

    for cache in ROOT.rglob("__pycache__"):
        if ".scratch" not in cache.parts:
            shutil.rmtree(cache)
            print(f"Removed {cache.relative_to(ROOT)}")
            removed += 1

    for file in FILES:
        if file.exists():
            file.unlink()
            print(f"Removed {file.relative_to(ROOT)}")
            removed += 1

    print(f"Cleaned {removed} generated path(s).")
    return 0

def run(command: list[str], *, cwd: Path = ROOT) -> None:
    print(f"> {' '.join(command)}", flush=True)
    result = subprocess.run(command, cwd=cwd, check=False)
    if result.returncode:
        raise SystemExit(result.returncode)

def require(command: str, install: str) -> None:
    if shutil.which(command) is None:
        raise SystemExit(f"{command} was not found. {install}")

